insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('nodal', 'beginner', 'module', 'm01-what-a-well-can-deliver', 1, 'Asking what a producing well will make is asking two questions at once. What does each of the two halves state?', '["Both halves state a rate, and the larger of the two is taken.", "The reservoir sets the wellhead pressure while the tubing sets the reservoir pressure, so the two are simply solved one after the other.", "The reservoir delivers a rate at a flowing pressure, and the tubing requires a pressure to lift a rate.", "The reservoir fixes the rate and the tubing fixes the pressure, with neither depending on the other."]'::jsonb, 2, 'The tubing requirement is not monotonic in rate, which is why the two statements can agree at more than one place.'),
  ('nodal', 'beginner', 'module', 'm01-what-a-well-can-deliver', 2, 'In what unit does the inflow half of this course carry bottomhole pressure, and what does the engine do with a value handed to it in another one?', '["Absolute pressure in psia, and the engine converts nothing at all and raises no warning about the unit.", "Gauge pressure in psig, which the engine converts to psia on entry.", "Either psia or psig, because the engine inspects the magnitude of every pressure supplied to it and infers which convention the caller meant.", "Absolute pressure in psia throughout, and a gauge value handed in is refused with an error before any curve is built."]'::jsonb, 0, 'Rate runs in stb/d alongside ft, degF, in and stb/d/psi, and none of those is converted either.'),
  ('nodal', 'beginner', 'module', 'm01-what-a-well-can-deliver', 3, 'BONNY-7 reaches an absolute open flow of 4324.444444 stb/d while it actually runs at 1355.714057 stb/d. What accounts for the gap between the two?', '["Rate dependent skin, which chokes the sandface long before the open flow is approached.", "The open flow is extrapolated past the lowest sampled row rather than read from the curve.", "The 0 psia in the open flow is a surface condition, so the two are quoted at different depths.", "The tubing, because the open flow assumes a sandface at zero psia that no real completion delivers."]'::jsonb, 3, 'Against a wellhead pressure of 420 psia that operating rate is 0.31350017 of the open flow, on a drawdown of 677.857029 psi.'),
  ('nodal', 'beginner', 'module', 'm01-what-a-well-can-deliver', 4, 'BONNY-7 carries a dead column of 2570 psia against a reservoir pressure of 2740 psia. What does that comparison establish about the well?', '["The column wins at zero rate, so the well needs a kick off to start.", "The reservoir wins at zero rate, standing 170 psi above the column, so the well starts on its own.", "Nothing at all, since a dead column is a property of the completion fluid and can never be compared with a reservoir pressure.", "The well is dead, because a column standing 170 psi heavier than the reservoir can never be unloaded at all."]'::jsonb, 1, 'A well whose column outweighs the reservoir at zero rate starts its residual positive, which is where a second crossing becomes possible.'),
  ('nodal', 'beginner', 'module', 'm01-what-a-well-can-deliver', 5, 'The published dead well case reads an inflow of 600.000000 psia against an outflow of 1890.000000 psia at 300 stb/d. What is that pair describing?', '["A combination with no crossing anywhere, so the status describes the pair and not the rock behind it.", "A reservoir with no productivity left in it at any rate.", "A solver that failed to converge, since a curve carrying an open flow of 600.000000 stb/d must cross some outflow requirement somewhere.", "An inflow curve built with its two pressures entered the wrong way round."]'::jsonb, 0, 'The case reports zero crossings on a curve whose absolute open flow is 600.000000 stb/d, so the reservoir itself is never in question.'),
  ('nodal', 'beginner', 'module', 'm01-what-a-well-can-deliver', 6, 'How is the residual formed at a stated rate, and what does a single change of sign in it mean?', '["Inflow supply times outflow requirement, with a sign change at each root.", "Inflow supply minus outflow requirement, and a change of sign only ever means the solver has stepped outside the sampled range of the curve.", "Outflow requirement minus inflow supply, and one change of sign means the pair has a single crossing.", "Reservoir pressure minus the flowing pressure at that rate, a difference which changes sign right at the operating point."]'::jsonb, 2, 'On BONNY-7 the residual runs from minus 192.336636 psi at 4.324444 stb/d to 12517.903995 psi at the highest sampled rate.'),
  ('nodal', 'beginner', 'module', 'm01-what-a-well-can-deliver', 7, 'Lowering the wellhead pressure on BONNY-7 from 420 psia to 280 psia moves the well to 1424.991968 stb/d. Which of the two curves moved?', '["Both moved, since a wellhead change alters the drawdown available.", "Only the outflow requirement moved, since the same inflow curve was simply read at a lower pressure.", "Only the inflow curve moved, because the reservoir responds to the reduced back pressure imposed on it at the surface.", "Neither moved, since the operating point is set by the reservoir alone."]'::jsonb, 1, 'Raising the same wellhead to 490 psia instead gives 1319.581001 stb/d at 2080.209500 psia, on that one unchanged inflow curve.'),
  ('nodal', 'beginner', 'module', 'm01-what-a-well-can-deliver', 8, 'Which inflow families does this engine carry for oil, and what is each one built from?', '["Vogel and the composite only, with anything else left to the caller.", "A straight line index, Vogel and the composite for oil, with back pressure and Houpeurt available as the two turbulent oil alternatives.", "Five separate oil families, each of which carries its own forward relation and an entirely independent inverse.", "A straight line index, Vogel, composite, Fetkovich and Jones, each from one forward rate function."]'::jsonb, 3, 'Deriving everything from the one forward definition is what stops a family carrying a forward relation and an inverse that disagree.'),
  ('nodal', 'beginner', 'module', 'm01-what-a-well-can-deliver', 9, 'Two published gas cases share a reservoir pressure of 4000 psia and report 13289.296319 and 5596.679697 Mscf/d. What does that pair show?', '["That one of the two cases must have been cut with a wrong z-factor.", "That gas open flows are quoted in Mscf/d and not MMscf/d, and nothing else differs.", "The family choice sets the deliverability, so back pressure and Houpeurt are not interchangeable.", "That the Houpeurt form is the conservative one and should be preferred."]'::jsonb, 2, 'Rawlins and Schellhardt takes a C of 0.01 and an n of 0.85 there, while Houpeurt takes an a of 900 and a b of 0.35.'),
  ('nodal', 'beginner', 'module', 'm01-what-a-well-can-deliver', 10, 'Why does the engine obtain a flowing pressure for a stated rate by a root find rather than by reading its own sampled table?', '["A chord across sampled rows is not the relation itself, so only the forward definition is solved.", "Because no closed form inverse exists for Vogel, Fetkovich, Jones, back pressure or Houpeurt, so a root find is the only route left.", "Because the sampled table holds only 40 rows for the published cases, and a table of that length cannot be interpolated by any method at all.", "Because a root find runs faster than any interpolation across a stored curve of the length these families produce."]'::jsonb, 0, 'The curve is sampled evenly in pressure rather than in rate, so it is sparsest in rate exactly where the bend is sharpest.'),
  ('nodal', 'beginner', 'module', 'm01-what-a-well-can-deliver', 11, 'Calibrated families read their own test rates back at 900.000000, 700.000000 and 1100.000000 stb/d. What does that column prove?', '["That all three calibrations were carried out correctly.", "Nothing about which family suits the well, since reproducing the test is what calibration means.", "That the straight line, Vogel and Fetkovich forms agree wherever they are read.", "That the tests were taken above the bubble point in each of the three cases."]'::jsonb, 1, 'One test carries no curvature, so it cannot separate a phase change effect from a turbulence effect either.'),
  ('nodal', 'beginner', 'module', 'm01-what-a-well-can-deliver', 12, 'What does the engine do to a Vogel curve when it is asked what that curve becomes at a lower reservoir pressure?', '["It holds the absolute open flow fixed and rescales the pressure axis underneath it, so the curve keeps its shape.", "It holds the productivity index, in the same way that the straight line and the composite do, because one depletion rule serves every oil family.", "It declines its fitted coefficient, in the way the Fetkovich family declines its own C as the reservoir pressure falls.", "It applies Eickmeier''s cube rule, taking 2400 psia down to 1800 psia for 632.812500 stb/d."]'::jsonb, 3, 'The rule answers what the curve would be at a lower pressure and says nothing whatever about when that pressure arrives.'),
  ('nodal', 'beginner', 'module', 'm01-what-a-well-can-deliver', 13, 'The first 360 psi of drawdown on BONNY-7 buys 720.000000 stb/d, while the slice from 391 psia down to 0 psia adds far less. What is that contrast?', '["The price of rate rising as it is spent, with the last slice lifting 4133.021538 to 4324.444444 stb/d.", "A sampling artefact, since the curve is sampled evenly in pressure.", "Evidence that the reservoir pressure of 2740 psia was estimated too high.", "The effect of the tubing, which sets the operating point on the curve."]'::jsonb, 0, 'Reaching 0.97006680 of the open flow costs a fall to 301.955326 psia, a comparable slice of pressure for a much smaller slice of rate.'),
  ('nodal', 'beginner', 'module', 'm01-what-a-well-can-deliver', 14, 'BONNY-7 prints minus 0.50000000 psi per stb/d at 216, 1297, 1946 and 2595 stb/d. What is that value exactly?', '["An average slope fitted by finite difference across the sampled rows, which is why it repeats at four separate rates.", "The slope of the outflow requirement, which is flat over that range of rate because friction has not yet grown large enough to matter.", "Minus one over its productivity index of 2.00000000 stb/d/psi, holding while the flow is undersaturated.", "Minus one over the absolute open flow divided by the reservoir pressure, which is the same thing on any curve."]'::jsonb, 2, 'The same column reads minus 0.57666066 at 3243 stb/d and minus 1.57442483 at 4195 stb/d, once the flowing pressure is below 1300 psia.'),
  ('nodal', 'beginner', 'module', 'm01-what-a-well-can-deliver', 15, 'Why can no reserve be booked from an inflow curve, however many decimal places its open flow carries?', '["Because the open flow is quoted at a sandface of zero psia.", "It describes one reservoir pressure with no time axis, so nothing integrates a rate into a volume.", "Because the curve holds no material balance and no drive mechanism, although a decline can still be recovered from the shape of its lower end.", "Because the inflow rate is total liquid and carries no water split."]'::jsonb, 1, 'Shifting the published straight line case to 2000 psia gives a future open flow of 3600.000000 stb/d and says nothing about when that pressure arrives.'),
  ('nodal', 'beginner', 'module', 'm02-the-straight-line', 1, 'A productivity index of 1.8 stb/d/psi stands against a reservoir pressure of 3200 psia. What open flow follows, and by what operation?', '["3600.000000 stb/d, the same index read from 2000 psia instead.", "5760.000000 stb/d, since the index multiplies the whole reservoir pressure at a sandface of zero.", "5760.000000 stb/d, but only once the root find has walked the sampled rows of the curve down to the axis and converged on the last of them.", "It cannot be stated without the bubble point, which every oil family requires."]'::jsonb, 1, 'That case carries a bubble point of 0 psia and 40 sampled rows, and the printed open flow closes by hand with no solver involved.'),
  ('nodal', 'beginner', 'module', 'm02-the-straight-line', 2, 'What in a printed curve identifies a straight line relation without a second model being run against it?', '["An open flow that divides exactly by the reservoir pressure.", "A rate of zero at the reservoir pressure, which no other oil family in this engine is able to reproduce at the top of its own curve.", "Rows spaced evenly in pressure, which is the sampling signature a linear relation leaves behind in the table it prints.", "A slope column holding one value throughout, that value being minus one over the productivity index."]'::jsonb, 3, 'On the published case that value is minus 0.55555556 psi per stb/d at 288.0000, 1152.0000, 2880.0000, 4608.0000 and 5472.0000 stb/d.'),
  ('nodal', 'beginner', 'module', 'm02-the-straight-line', 3, 'BONNY-7 holds minus 0.50000000 psi per stb/d as far as 2595 stb/d and then reads minus 0.57666066 at 3243 stb/d. What follows from that?', '["Its curve stops being a straight line, and the slope column says so with no bubble point supplied.", "The sampling has become too coarse to resolve the lower rows.", "The index has been recalibrated between the two rates.", "The well has entered turbulent flow, the only mechanism able to move a slope column."]'::jsonb, 0, 'The flowing pressures behind those two rates are 1442.500000 and 1105.576792 psia, straddling a bubble point of 1300 psia.'),
  ('nodal', 'beginner', 'module', 'm02-the-straight-line', 4, 'Handed somebody else''s curve and none of the inputs behind it, how is the productivity index recovered?', '["By dividing the absolute open flow by the reservoir pressure.", "By fitting a least squares line through the sampled rows, which returns the index whatever family produced the curve in the first place.", "By negating and inverting the slope column, since open flow over reservoir pressure works only on a line.", "By reading the rate at half the reservoir pressure and doubling it."]'::jsonb, 2, 'BONNY-7''s 4324.444444 stb/d over 2740 psia is not its 2.00000000 stb/d/psi, because the curve is not linear all the way down.'),
  ('nodal', 'beginner', 'module', 'm02-the-straight-line', 5, 'BONNY-7''s straight line and composite differ by 0.000000 stb/d at 2740, 2380, 1957, 1566 and 1300 psia. Why does that column of zeros appear?', '["Both families were calibrated from the same test point at 2380 psia.", "The engine rounds every printed rate to six decimal places, which hides differences of the size the two families actually carry up there.", "The composite defaults to the straight line whenever a bubble point is supplied.", "Above the bubble point the composite holds nothing but the line, so the two are one and the same curve."]'::jsonb, 3, 'Both families carry one index, so a wrong index makes them wrong together and in the same direction, and their agreement is evidence about formulas.'),
  ('nodal', 'beginner', 'module', 'm02-the-straight-line', 6, 'Where does that agreement end on BONNY-7, and how large is the first departure between the two families?', '["At the test pressure of 2380 psia, with a departure of 720.000000 stb/d.", "At the bubble point of 1300 psia, and the first departure is 10.855385 stb/d, which no chart would show.", "At 0 psia, where the difference of 1155.555556 stb/d appears all at once.", "At 1174 psia, and the departure of 182.761709 stb/d there is large enough to read straight off a chart."]'::jsonb, 1, 'The difference grows without limit below the join, reaching 564.978462 stb/d at 391 psia and 1155.555556 stb/d at the axis.'),
  ('nodal', 'beginner', 'module', 'm02-the-straight-line', 7, 'What must be true of a well before a straight line can be used on it without extrapolating past the evidence?', '["The well must have been tested at more than one rate.", "The bubble point must be supplied to the straight line family before it will run.", "The reservoir pressure sits above the bubble point and the flow stays above it at the rates intended.", "The reservoir pressure sits above the bubble point, which on its own is enough."]'::jsonb, 2, 'BONNY-7 reads 2880.000000 stb/d at its bubble point, so any rate below that is exact, while FORCADOS-3 reaches only 1996.364220 stb/d at its own.'),
  ('nodal', 'beginner', 'module', 'm02-the-straight-line', 8, 'BONNY-7 was tested at 720 stb/d and a flowing pressure of 2380 psia. What index do the straight line and the composite each back out?', '["Both return 2.00000000 stb/d/psi, an index error of 0.00000000 stb/d/psi at a test above the bubble point.", "The line returns 2.00000000 and the composite 1.57194033 stb/d/psi.", "Both return an index near 1.578 stb/d/psi, since 720 stb/d spread over the full 2740 psi of the reservoir pressure is what calibration divides by.", "The line returns 2.00000000 stb/d/psi and the composite refuses, because a test taken above the bubble point leaves its saturated block unpinned."]'::jsonb, 0, 'Above the bubble point dividing the test rate by the test drawdown is not an approximation to the correct operation, it is the correct operation.'),
  ('nodal', 'beginner', 'module', 'm02-the-straight-line', 9, 'FORCADOS-3 was tested at 2400 stb/d and 2180 psia against a bubble point of 2450 psia. What does dividing by the test drawdown return?', '["1.55844156 stb/d/psi, which is high by 0.01349877 stb/d/psi.", "An index the engine refuses to print, because a test below the bubble point cannot pin a straight line and the family raises a warning instead.", "1.57194033 stb/d/psi, which is what dividing rate by drawdown always returns.", "1.55844156 stb/d/psi against the composite''s 1.57194033, so the index comes out low."]'::jsonb, 3, 'Of the 1540 psi of test drawdown only the first 1270 psi lay above the bubble point, where the well genuinely obeyed its index.'),
  ('nodal', 'beginner', 'module', 'm02-the-straight-line', 10, 'On FORCADOS-3 the gap between the families changes sign at 2180 psia rather than at 2450 psia. Why at that pressure?', '["Because 2180 psia is where the composite hands over to its Vogel half.", "Because the sampled rows are spaced evenly in pressure and 2180 psia happens to be one of the 45 rows that this particular well carries.", "Calibration forces every family through the test point, so a wrong slope swings about that pressure.", "Because the bubble point of 2450 psia was entered wrongly, and the true bubble point of the fluid is the pressure at which the two curves cross."]'::jsonb, 2, 'At 2450 psia the straight line is minus 17.143440 stb/d against the composite, near the largest negative value in that whole column.'),
  ('nodal', 'beginner', 'module', 'm02-the-straight-line', 11, 'What two conditions must hold before a drawdown means anything, and which of them does the engine check?', '["Both pressures absolute and referred to one datum, and the engine checks neither of the two.", "Both pressures absolute and at one datum, and the engine checks both.", "Both from one month and one datum, and the engine checks the datum by depth.", "Both pressures gauge and at one datum, since the atmosphere cancels out."]'::jsonb, 0, 'A gauge reading against an absolute one is wrong by an atmosphere, and a gauge at the wrong depth adds a fluid column that has nothing to do with the flow.'),
  ('nodal', 'beginner', 'module', 'm02-the-straight-line', 12, 'During a flow test, which of the two pressures behind a productivity index is actually measured at the well?', '["Both, which is why an index is the best conditioned number in the subject.", "Only the flowing pressure, as the reservoir pressure comes from a build-up, a survey or a model.", "Only the reservoir pressure, since the flowing pressure has to be inferred from the surface rate through an assumed tubing traverse.", "Neither, because both are reported at the wellhead and carried down to the sandface by a correlation."]'::jsonb, 1, 'The reservoir pressure is an average over a drainage area, so a small drawdown test measures rate precisely and index fragilely.'),
  ('nodal', 'beginner', 'module', 'm02-the-straight-line', 13, 'BONNY-7''s budget of 2740 psi reaches 4324.444444 stb/d while FORCADOS-3''s larger budget of 3720 psi reaches only 4135.949669 stb/d. Why?', '["Its operating drawdown of 1353.090778 psi is the larger of the two, so more of its budget is already spent.", "Its reservoir pressure was estimated from a build-up rather than measured, so the extra 980 psi of budget is not real and cannot buy any rate.", "Its index is smaller and its bubble point leaves only the first 1270 psi in the linear region.", "Its curve carries 45 sampled rows against 51, so the lower end of it is resolved too coarsely for the open flow to be read off accurately."]'::jsonb, 2, 'Nobody spends the budget in any case, since BONNY-7 runs at a drawdown of 677.857029 psi with the tubing setting the operating point.'),
  ('nodal', 'beginner', 'module', 'm02-the-straight-line', 14, 'On BONNY-7 a flowing pressure of 1566 psia and a drawdown of 1566 psi are two different states. What makes confusing them dangerous?', '["Both land on the well''s own curve, giving 2348.000000 and 3121.144615 stb/d with nothing looking wrong.", "A drawdown of 1566 psi falls outside the sampled range of the curve, so the engine returns an error rather than a rate.", "The engine warns whenever a drawdown is supplied where a pressure was expected, so the confusion is caught but the run has to be repeated.", "The two differ by an atmosphere, which is the same error as reading a gauge pressure into a slot that was asking for an absolute one."]'::jsonb, 0, 'The matching pair is a flowing pressure of 1174 psia against a drawdown of 1174 psi, and both of those sit on the curve as well.'),
  ('nodal', 'beginner', 'module', 'm02-the-straight-line', 15, 'The Jones case carries a bubble point of 0 psia and still bends from its very first sampled rate. What does that establish?', '["That its a and b coefficients miss its own test point by more than 2 percent, so the fit is the source of the bend.", "A bending curve is no proof of a bubble point, since turbulence bends one with no phase change.", "That a bubble point of 0 psia is a placeholder rather than a real input, and the family quietly substitutes the reservoir pressure in its place.", "That the Jones family is unsuitable for any well whose fluid is undersaturated, because the bend it produces has no physical cause behind it."]'::jsonb, 1, 'Its slope runs from minus 1.06482135 psi per stb/d at 54.9405 stb/d to minus 4.03160570 at 1043.8686 stb/d, with no flat stretch at all.'),
  ('nodal', 'beginner', 'module', 'm03-below-the-bubble-point', 1, 'What is the dominant reason productivity per psi falls once the flowing pressure drops below the bubble point?', '["The oil shrinks, which is the largest of the three effects at work.", "The reservoir pressure itself falls as gas is liberated, so the drawdown available to the well is reduced by the same amount at every rate.", "Turbulence begins near the sandface as soon as free gas starts to move there.", "Gas comes out of solution and takes up pore space, so effective permeability to oil falls."]'::jsonb, 3, 'The liberated gas also leaves the remaining oil more viscous, and all of it happens near the wellbore where most of the drawdown is spent.'),
  ('nodal', 'beginner', 'module', 'm03-below-the-bubble-point', 2, 'BONNY-7 begins to bend at 2880.000000 stb/d and FORCADOS-3 at 1996.364220 stb/d. What do those two rates have in common?', '["Both are roughly two thirds of the open flow of their own well.", "Neither travels anywhere, since each follows from three inputs while the bend itself starts at a pressure.", "Both mark the rate at which turbulence takes over from phase change, which is a property of the completion rather than of the fluid in place.", "Both are sampled rows rather than real quantities, since the curve is spaced evenly in pressure and lands on those rates by chance."]'::jsonb, 1, 'BONNY-7''s last flat slope row sits at 1442.500000 psia and its first moving row at 1105.576792 psia, either side of a bubble point of 1300 psia.'),
  ('nodal', 'beginner', 'module', 'm03-below-the-bubble-point', 3, 'The published Vogel case reads minus 0.91168461 psi per stb/d at its very first sampled rate. What does that say about the reservoir behind it?', '["Its permeability is low, which steepens the whole slope column.", "Its bubble point was entered as 0 psia, which is what removes the flat stretch from the top of any curve the family produces.", "Its pressure is at or below the bubble point, so no undersaturated block exists anywhere on the curve.", "It is turbulent, since a slope moving at the first row is turbulence''s signature."]'::jsonb, 2, 'That column continues to minus 1.24939025 psi per stb/d at 750.0000 stb/d and minus 3.57770876 at 1425.0000 stb/d, holding still nowhere.'),
  ('nodal', 'beginner', 'module', 'm03-below-the-bubble-point', 4, 'What is the only coefficient a Vogel curve carries, and where on the curve does it sit?', '["The absolute open flow, which is the rate the expression returns at a flowing pressure of zero.", "The productivity index, read at the top of the curve.", "The pressure at half the open flow, which is what pins the shape of the curve.", "The bubble point, since the expression squares the flowing pressure divided by it."]'::jsonb, 0, 'The constants 0.2 and 0.8 came from Vogel''s 1968 computed solution gas drive cases and are not adjustable by the user.'),
  ('nodal', 'beginner', 'module', 'm03-below-the-bubble-point', 5, 'On the published Vogel case at a reservoir pressure of 2400 psia, what flowing pressure does half of the open flow require?', '["1200.000000 psia, which is half of the reservoir pressure.", "1620.937271 psia, comfortably above half the reservoir pressure because the relation is not a line.", "1215.702953 psia, which is the pressure at half the open flow once Eickmeier''s cube rule has taken the curve down to 1800 psia.", "600.000000 psia, where the curve reads 1350.000000 stb/d of its maximum."]'::jsonb, 1, 'At 1200 psia, exactly half the reservoir pressure, the curve is already at 1050.000000 of 1500.000000 stb/d.'),
  ('nodal', 'beginner', 'module', 'm03-below-the-bubble-point', 6, 'Vogel reads 2344.186047 stb/d at BONNY-7''s bubble point of 1300 psia where the composite reads 2880.000000 stb/d. Why is that row the argument?', '["Vogel has been calibrated from a test taken below the bubble point.", "The 535.813953 stb/d of difference is the largest anywhere on the curve, so it is the row on which the two families disagree most sharply.", "The composite is wrong at that row, because its two halves are joined there and the join is where a construction is least reliable.", "The well is genuinely linear there, so Vogel has bent a stretch of curve that does not bend."]'::jsonb, 3, 'Being low by 1091.197244 stb/d at the axis is a margin nobody chose, and it lands on top of whatever margin the engineer thought was being added.'),
  ('nodal', 'beginner', 'module', 'm03-below-the-bubble-point', 7, 'How does Standing''s construction assemble the two halves of a composite inflow curve?', '["A line above the bubble point and Vogel''s shape below it, with one index carrying both.", "Two straight lines of different slope, meeting at the bubble point.", "A Vogel curve above the bubble point and a line below it, since the fluid is undersaturated in the bulk of the drainage area and saturated at the sandface.", "Vogel''s shape throughout, scaled by the productivity index."]'::jsonb, 0, 'Below the join the extra rate is Vogel''s shape scaled by the index times the bubble point over 1.8, with the flowing pressure divided by the bubble point.'),
  ('nodal', 'beginner', 'module', 'm03-below-the-bubble-point', 8, 'The saturated block is 1444.444444 stb/d on BONNY-7 and 2139.585450 stb/d on FORCADOS-3. What decides its size?', '["The reservoir pressure, which is larger on the second of the two wells.", "The difference between the reservoir pressure and the bubble point, which is 1440 psi on one well and 1270 psi on the other one.", "Only the index and the bubble point, which is why the smaller index carries the larger block here.", "The share of the open flow lying below the join, being 0.33401850 on one well and 0.51731419 on the other."]'::jsonb, 2, 'FORCADOS-3 has the smaller index at 1.57194033 stb/d/psi and still the larger saturated block, because its bubble point of 2450 psia is far higher.'),
  ('nodal', 'beginner', 'module', 'm03-below-the-bubble-point', 9, 'What single multiplication can be checked by hand against BONNY-7''s printed rate at 1300 psia?', '["2.00000000 stb/d/psi times the reservoir pressure of 2740 psia.", "2.00000000 stb/d/psi times 1440.0000 psi of drawdown, giving 2880.000000 stb/d exactly.", "2.00000000 stb/d/psi times 1300.0000 psi, the bubble point read as a drawdown.", "The index times the bubble point over 1.8, which is the saturated block."]'::jsonb, 1, 'That product is also the printed undersaturated block, so three published numbers stand in one exact arithmetic relation with no tolerance anywhere.'),
  ('nodal', 'beginner', 'module', 'm03-below-the-bubble-point', 10, 'Why does the Vogel term contribute nothing at all at the bubble point of a composite curve?', '["Its argument is the flowing pressure over the bubble point, which is one, where the shape is zero.", "Because the engine clamps the term to zero at that single row.", "Because the term is scaled by the index times the bubble point over 1.8, and that scale factor falls to zero as the join is approached from below.", "Because the two halves are forced to meet by the calibration step, which pins them to a common value at the join."]'::jsonb, 0, 'The slope is continuous there as well, since differentiating that term at the join returns minus one over the productivity index.'),
  ('nodal', 'beginner', 'module', 'm03-below-the-bubble-point', 11, 'What does a bubble point set too low do to a composite curve built on it?', '["It clamps the curve to Vogel from the first psi of drawdown.", "It shortens the linear stretch, so the rate at the join is low and the block large.", "It runs the linear stretch too far, so the rate at the join is high and the saturated block small.", "It leaves the curve unchanged, since the saturated block depends on the index alone."]'::jsonb, 2, 'Set to 0 psia the saturated block vanishes and BONNY-7 reports 5480.000000 stb/d on a curve of perfectly constant slope, with no warning raised.'),
  ('nodal', 'beginner', 'module', 'm03-below-the-bubble-point', 12, 'An engineer derives an index, a bubble point and a reservoir pressure from one below bubble test read as a straight line. What does the join identity then show?', '["It fails to close by exactly the amount the index was corrupted by, which is how a below bubble test is caught.", "It closes only to the precision the index is printed at, and that shortfall is the diagnostic which reveals the test was taken below the bubble point.", "It cannot be formed at all, because a straight line family carries no bubble point and so offers no join to check.", "It still closes, since it tests the three inputs against each other and never against the well."]'::jsonb, 3, 'An identity says three printed numbers stand in an exact relation, and two implementations of one wrong formula will agree with each other perfectly.'),
  ('nodal', 'beginner', 'module', 'm03-below-the-bubble-point', 13, 'BONNY-7 was tested above its bubble point. What separates the straight line, the composite and Vogel on that well?', '["Nothing in the index, only extrapolation below the test, at 5480.000000, 4324.444444 and 3233.247201 stb/d.", "Nothing at all, since the three families agree everywhere on it.", "The index, which is 2.00000000 stb/d/psi for the line and lower for the other two families.", "The rate at the test pressure, which each family reproduces to a slightly different figure."]'::jsonb, 0, 'The ordering never crosses: the straight line reads high, the composite sits in the middle and Vogel reads low, everywhere below the test.'),
  ('nodal', 'beginner', 'module', 'm03-below-the-bubble-point', 14, 'FORCADOS-3''s test at 2180 psia sits below its bubble point. What does reading that test as a straight line do to the index?', '["It returns an index too high by 0.01349877 stb/d/psi, because the bend flatters the drawdown that was measured.", "It returns the same 1.57194033 stb/d/psi, since calibration forces every family through the test point and the index is what that forcing pins.", "It returns 1.55844156 rather than 1.57194033 stb/d/psi, so the index is understated.", "It leaves the index alone and moves only the shape, which is why a model choice below the bubble point is a choice about extrapolation."]'::jsonb, 2, 'The well had already begun to bend before it was measured, so it delivered less over the whole drawdown than a true line at the correct index would have.'),
  ('nodal', 'beginner', 'module', 'm03-below-the-bubble-point', 15, 'Every family reproduces its own test exactly. What kind of test carries the curvature needed to choose between them?', '["A build-up, which returns the reservoir pressure and the permeability that every one of the families shares.", "A multi-rate test, since one point fits every family and is therefore evidence for none of them.", "A single test taken below the bubble point, because the bend it sits on is what distinguishes one family shape from another.", "No test can, since the engine accepts any family for any well and prints an open flow to six decimal places without warning."]'::jsonb, 1, 'The five published calibrations read back 900.000000, 700.000000, 600.000000, 1500.000000 and 1100.000000 stb/d at their own test pressures.'),
  ('nodal', 'beginner', 'module', 'm04-reading-the-curve-both-ways', 1, 'What does a forward inflow reading, rate from a stated flowing pressure, actually require of the engine?', '["One evaluation of the family''s defining expression, with no bracket, no search and no tolerance in it.", "A bracketed search between 0 psia and the reservoir pressure.", "A linear interpolation between the two stored rows that straddle the requested flowing pressure, then a refinement pass.", "A closed form rearrangement picked from one of five stored inverse formulas, one written for each oil family."]'::jsonb, 0, 'Every family is written as rate from pressure, so the forward direction is the definition itself and not a derived operation.'),
  ('nodal', 'beginner', 'module', 'm04-reading-the-curve-both-ways', 2, 'On the published straight line case at 3200 psia with an index of 1.8 stb/d/psi, what does the slope column show?', '["A slope steepening steadily as the rate approaches the open flow.", "A slope of -0.55555556 psi per stb/d above the bubble point of 0 psia and a much steeper one below it near the open flow.", "A single value of -0.55555556 psi per stb/d at every sampled rate, which is minus one over the index.", "A slope equal to the reservoir pressure divided by the open flow at each sampled rate."]'::jsonb, 2, 'That case reads 288.0000, 1152.0000, 2880.0000, 4608.0000 and 5472.0000 stb/d at the same price per barrel.'),
  ('nodal', 'beginner', 'module', 'm04-reading-the-curve-both-ways', 3, 'What do the first and the last 240 psi of drawdown buy on the published Vogel case, 2400 psia with an open flow of 1500 stb/d?', '["Each buys the same 258.000000 stb/d, since a Vogel curve is symmetric.", "The first buys 258.000000 stb/d while the last lifts the reading from 1458.000000 to 1500.000000 stb/d.", "The first buys 42.000000 stb/d and the last 258.000000 stb/d, because a Vogel curve steepens as the flowing pressure falls.", "The first buys 600.000000 stb/d and the last a further 1050.000000 stb/d on top of it."]'::jsonb, 1, 'The same case reads 600.000000 stb/d at 1800 psia and 1050.000000 stb/d at 1200 psia, so most of the rate arrives early.'),
  ('nodal', 'beginner', 'module', 'm04-reading-the-curve-both-ways', 4, 'Why does carrying BONNY-7''s straight line reading into the block below its bubble point go unnoticed at first?', '["The engine prints a warning once the gap passes 100 stb/d.", "Both families are sampled on the same rows, so the two curves cannot separate until the stored rows run out below 391 psia.", "The composite reads high rather than low there, so the error flatters the well and gets welcomed.", "At 1174 psia the two answers differ by only 10.855385 stb/d, an amount that reads exactly like rounding."]'::jsonb, 3, 'By 391 psia the same habit is 564.978462 stb/d wrong, and by 0 psia it is 1155.555556 stb/d wrong.'),
  ('nodal', 'beginner', 'module', 'm04-reading-the-curve-both-ways', 5, 'Three families calibrated from BONNY-7''s single test all read 720.000000 stb/d at 2380 psia. What happens at 0 psia?', '["They separate to 5480.000000, 3233.247201 and 4324.444444 stb/d, so no reading names the family.", "They stay within about 10.855385 stb/d of one another there.", "They converge on the composite value of 4324.444444 stb/d, because every family has to return one absolute open flow.", "They cannot be read at 0 psia at all, since that pressure falls outside the sampled table entirely."]'::jsonb, 0, 'The evidence about which family fits lives where no measurement exists, which is why one test ranks nothing.'),
  ('nodal', 'beginner', 'module', 'm04-reading-the-curve-both-ways', 6, 'Why does the engine solve the calibrated relation backwards instead of storing one inverse formula per family?', '["Closed form inverses evaluate more slowly than Brent''s method.", "The forward relations are not monotone, so no closed form inverse exists for any of the five oil families at all.", "A single search keeps the physics in one place, so a family added later cannot leave a stale inverse behind.", "Closed forms exist only for gas, because the oil families carry integrals inside them."]'::jsonb, 2, 'The closed forms survive in the oracle that checks the engine, which is where a second opinion belongs.'),
  ('nodal', 'beginner', 'module', 'm04-reading-the-curve-both-ways', 7, 'What guarantees that a bracketed search for a flowing pressure holds exactly one root?', '["Brent''s method converges whatever the shape of the function.", "The relation reads zero at the reservoir pressure and the open flow at 0 psia, and is monotone between.", "The stored rows are evenly spaced in pressure, so a sign change can never fall between two consecutive samples.", "The composite is continuous in both value and slope at the bubble point, removing the one place a second root could hide."]'::jsonb, 1, 'Brent falls back to bisection whenever its secant or inverse quadratic step misbehaves, so the bracket is never lost.'),
  ('nodal', 'beginner', 'module', 'm04-reading-the-curve-both-ways', 8, 'BONNY-7''s composite reads 2880.000000 stb/d at its bubble point against an undersaturated block of 2880.000000 stb/d. What does that show?', '["The curve is continuous at the join but not smooth, its slope moving from -0.50000000 to -0.57666066.", "The composite and the straight line agree at every pressure.", "The join was fitted by least squares, so the two blocks meet only to printing precision.", "The bubble point was chosen to make the two blocks agree, which is why the identity closes."]'::jsonb, 0, 'Rearranging by hand means deciding which block the answer lands in before you have the answer, while a search walks across the join.'),
  ('nodal', 'beginner', 'module', 'm04-reading-the-curve-both-ways', 9, 'An inverse reading is asked for at a rate above BONNY-7''s open flow of 4324.444444 stb/d. What comes back?', '["A warning that the rate falls outside the sampled table.", "The open flow itself, since the engine clamps any request above the largest rate the relation supports and says so.", "A negative flowing pressure, the bracket continued past 0 psia, which downstream code can at least test for before it uses the number.", "Zero pressure, which is the end of the bracket rather than a solved root, and it prints like an answer."]'::jsonb, 3, 'The published Fetkovich case tops out at 124.766308 stb/d, and anything asked beyond that gets the same boundary reply.'),
  ('nodal', 'beginner', 'module', 'm04-reading-the-curve-both-ways', 10, 'The engine walks its gas curve evenly in pressure over forty steps. Why does the largest bias land at the low rate end?', '["Forty steps are too few to resolve a gas curve at any rate.", "Squared pressures make rate move fastest near the reservoir pressure, so the rate spacing is widest there.", "The samples crowd at the low rate end, so a chord there averages the curvature away.", "The low rate end sits closest to 0 psia, where the stored table carries no rows at all."]'::jsonb, 1, 'Even in pressure is wildly uneven in rate, and the widest rate interval sits where the curve bends hardest.'),
  ('nodal', 'beginner', 'module', 'm04-reading-the-curve-both-ways', 11, 'What is the sign of the chord error when a gas inflow is read off its sampled rows?', '["Random, depending on where the requested rate happens to fall.", "High near the reservoir pressure and low near the open flow, so the two errors cancel.", "Always low, since a chord across a curve that bends one way is biased in that direction every time.", "Low on the turbulent case and high on the two better behaved empirical families."]'::jsonb, 2, 'Measured biases run -1.477901 psi at 1328.9296 Mscf/d on the Rawlins and Schellhardt case and -3.878569 psi at 559.6680 Mscf/d on the Houpeurt one.'),
  ('nodal', 'beginner', 'module', 'm04-reading-the-curve-both-ways', 12, 'Why is the strongly turbulent case, C of 0.004 and n of 0.62 at 3200 psia, hit hardest at 8.8807 Mscf/d?', '["Its lower exponent gives a steeper approach to the reservoir pressure, so the chord crosses a harder bend.", "Its open flow of 88.806747 Mscf/d is the smallest of the three cases, so one pressure step covers a larger share of its rate range.", "Its reservoir pressure of 3200 psia is below the 4000 psia of the other two, so each of its forty pressure steps is smaller.", "It carries fewer stored rows than the other gas cases, having been sampled over twenty pressure steps rather than forty."]'::jsonb, 0, 'The bias there is 12.910810 psi low against 0.933888 psi low at 31.0824 Mscf/d on the very same curve.'),
  ('nodal', 'beginner', 'module', 'm04-reading-the-curve-both-ways', 13, 'What happens to a solved gas well rate when the inflow is taken from the table instead of the relation?', '["Nothing, because the node solver reads its inflow from the calibrated relation directly and never touches the stored rows.", "The rate moves by several hundred Mscf/d, which is why the engine refuses to hand a sampled curve to the node solver.", "The rate rises by 0.638815 Mscf/d, because a chord drawn across a convex curve lies above it and overstates the pressure available.", "The vertical well shifts from 11335.720032 to 11335.081217 Mscf/d, a small and wholly systematic loss."]'::jsonb, 3, 'The deviated big tubing well moves the same way, from 8409.180054 to 8408.149052 Mscf/d.'),
  ('nodal', 'beginner', 'module', 'm04-reading-the-curve-both-ways', 14, 'Oil curves ship as tables too, 40 rows on the published cases and 51 on BONNY-7. Why is there no chord bias on them?', '["Oil relations are linear in pressure, so a chord drawn between any two stored rows lands exactly on the curve.", "The stored rows exist for drawing, and the engine answers an oil reading from the relation itself.", "The oil tables carry more rows than the gas tables, so their interpolation error falls below the printing precision.", "Each oil family carries a closed form inverse, one written per family, which is used in place of any bracketed search."]'::jsonb, 1, 'Ask BONNY-7 for the pressure at 3243 stb/d and 1105.576792 psia comes back wherever the stored rows happen to fall.'),
  ('nodal', 'beginner', 'module', 'm04-reading-the-curve-both-ways', 15, 'The published straight line reads an open flow of 5760.000000 stb/d at 3200 psia and 3600.000000 stb/d at 2000 psia. What does that pair demonstrate?', '["The index was recalibrated between the two readings.", "The straight line family gives up its index below the bubble point of 0 psia.", "No reading can say the reservoir pressure behind it is current, and the two print with equal confidence.", "A stale reservoir pressure turns up as an entry in the engine''s warnings list."]'::jsonb, 2, 'A reading is a property of the relation you calibrated, and the relation has no clock in it at all.'),
  ('nodal', 'beginner', 'module', 'm05-absolute-open-flow', 1, 'Which operation produces an absolute open flow?', '["A separate deliverability model fitted against the same test point.", "The forward reading of the calibrated relation at a flowing pressure of 0 psia, and nothing else.", "An inverse reading at the lowest rate the stored rows carry, then extended onto the axis by a short extrapolation.", "The reservoir pressure divided by the productivity index, which is why the answer has the units of a rate."]'::jsonb, 1, 'It is not a separate calculation and not a separate model, so any family that reads forwards already carries one.'),
  ('nodal', 'beginner', 'module', 'm05-absolute-open-flow', 2, 'How is the open flow built on each of a straight line, a Vogel curve and a composite?', '["All three divide the reservoir pressure by the curve''s slope.", "Index times reservoir pressure on all three, since every family becomes a straight line once the flowing pressure reaches zero.", "Index times bubble point on the first two, and index times reservoir pressure on the composite.", "Index times reservoir pressure, then the Vogel parameter itself, then two blocks summed on the composite."]'::jsonb, 3, 'Because the open flow is the only Vogel coefficient, calibrating that family from a test amounts to solving for it.'),
  ('nodal', 'beginner', 'module', 'm05-absolute-open-flow', 3, 'BONNY-7 carries an index of 2.00000000 stb/d/psi at 2740 psia with a bubble point of 1300 psia. How does its open flow split?', '["An undersaturated block of 2880.000000 stb/d and a saturated block of 1444.444444 stb/d, summing to 4324.444444.", "Evenly, at 2880.000000 stb/d in each of its two blocks.", "A saturated block of 2880.000000 stb/d and an undersaturated one of 1444.444444, most of the drawdown being spent below the join.", "Two blocks of 2880.000000 and 1444.444444 stb/d whose sum also equals the index times the full 2740 psia."]'::jsonb, 0, 'Its saturated share is 0.33401850, against 0.51731419 on FORCADOS-3.'),
  ('nodal', 'beginner', 'module', 'm05-absolute-open-flow', 4, 'Why does FORCADOS-3 carry the larger saturated share, 0.51731419 against 0.33401850, on the smaller index?', '["Its reservoir pressure of 3720 psia is the higher of the two.", "Its test of 2400 stb/d at 2180 psia sat below the bubble point, and a below bubble test shifts the split between blocks.", "The saturated block turns on index and bubble point alone, and its bubble point of 2450 psia is far higher.", "Its open flow of 4135.949669 stb/d is the smaller of the two, so a saturated block of fixed size becomes a larger share of it."]'::jsonb, 2, 'The blocks are 1996.364220 and 2139.585450 stb/d, and only the first of those knows the reservoir pressure.'),
  ('nodal', 'beginner', 'module', 'm05-absolute-open-flow', 5, 'Calibrated from a test of 1100 stb/d at 2900 psia against 3500 psia, what does the Fetkovich family return?', '["An open flow of 124.766308 stb/d, the family''s published value.", "An open flow of 3017.886603 stb/d on a backed out C, with only that one coefficient having moved.", "An open flow of 3017.886603 stb/d together with a revised exponent n.", "A warning, since a Fetkovich curve cannot be pinned from a single rate and pressure pair."]'::jsonb, 1, 'The backed out C is 0.0020560066733860726, against 0.000085 on the published case at the same reservoir pressure.'),
  ('nodal', 'beginner', 'module', 'm05-absolute-open-flow', 6, 'What part does the open flow play in an inverse reading?', '["It sets the tolerance that the bracketed search converges inside.", "It is the starting guess Brent''s method refines, which is why a poor open flow slows the search rather than breaking it.", "It fixes how many rows the sampled curve carries, one row for each percent of the open flow.", "It is the far end of the bracket, so a rate at or above it falls outside and gets zero pressure back."]'::jsonb, 3, 'What guarantees a root inside the bracket is that the relation reads zero at one end and the open flow at the other.'),
  ('nodal', 'beginner', 'module', 'm05-absolute-open-flow', 7, 'What physical condition does a flowing bottomhole pressure of 0 psia describe?', '["An absolute vacuum at the sandface beneath a standing column of fluid, useful as an anchor only.", "A wellhead pressure of zero with the tubing column still full, so the sandface still carries the whole weight of the fluid.", "The lowest pressure a facility could pull with artificial lift, which is why the number gets quoted as a maximum deliverability.", "Atmospheric pressure at the sandface, since a zero read on a gauge stands one atmosphere above an absolute zero."]'::jsonb, 0, 'A boundary condition need not be attainable to be useful, and this one anchors the far end of the curve.'),
  ('nodal', 'beginner', 'module', 'm05-absolute-open-flow', 8, 'Why is the open flow so often read as a rate a facility could be sized around?', '["The engine labels it as a deliverability in its own output.", "It is the only number on an inflow report checked against a measured production test.", "It carries the units of a rate and is the largest number on the page, which invites exactly that reading.", "It is the one reading that does not depend on which family was chosen for the curve."]'::jsonb, 2, 'BONNY-7 runs at 1355.714057 stb/d against an open flow of 4324.444444 stb/d, and the gap is the tubing rather than waste.'),
  ('nodal', 'beginner', 'module', 'm05-absolute-open-flow', 9, 'BONNY-7 reaches 0.90000000 of its open flow at 649.199606 psia. What does 0.97006680 of it cost?', '["Nothing more, the curve being flat that close to the open flow.", "A further fall to 301.955326 psia, out of a reservoir pressure of only 2740 psia to spend in the first place.", "A rise to 936.904430 psia, the required pressure turning upward past nine tenths of open flow.", "A fall to 1105.576792 psia, which is where the slope first leaves -0.50000000 psi per stb/d."]'::jsonb, 1, 'FORCADOS-3 does the same, needing 936.904430 psia at 0.89991424 and 420.700695 psia at 0.97003115 of its open flow.'),
  ('nodal', 'beginner', 'module', 'm05-absolute-open-flow', 10, 'Taking the published Fetkovich case from 3500 psia to 2500 psia does what to its open flow?', '["It holds at 124.766308 stb/d, C and n belonging to the completion.", "It falls from 124.766308 to 49.625684 stb/d by the same cube rule that takes the Vogel case from 1500.000000 to 632.812500.", "It falls to 3600.000000 stb/d, the value the published straight line reaches once it is shifted to 2000 psia.", "It falls from 124.766308 to 49.625684 stb/d, so an open flow quoted alone names nothing definite."]'::jsonb, 3, 'Fetkovich declines its C while Vogel follows Eickmeier''s cube rule, and neither rule says when the lower pressure arrives.'),
  ('nodal', 'beginner', 'module', 'm05-absolute-open-flow', 11, 'One test on FORCADOS-3, 2400 stb/d at 2180 psia, yields three different open flows. Which are they?', '["5797.402597, 3946.987127 and 4135.949669 stb/d, from one well, one test and one day of measurement.", "4135.949669 stb/d on all three, the test having pinned the curve at the one point where the families are forced to agree.", "5480.000000, 3233.247201 and 4324.444444 stb/d, which are the three values BONNY-7 returns from its own single test.", "5797.402597 and 4135.949669 stb/d only, Vogel refusing a well whose reservoir pressure stands above its bubble point."]'::jsonb, 0, 'An open flow is a property of the family as much as of the well, which is why it cannot travel without one.'),
  ('nodal', 'beginner', 'module', 'm05-absolute-open-flow', 12, 'A published node case is recorded dead, with zero crossings. What is its open flow?', '["Zero stb/d, since a well recorded dead has no inflow left to report and its open flow follows the operating rate down.", "600.000000 stb/d, but the engine suppresses it and returns a null open flow whenever the outflow stands above the inflow.", "600.000000 stb/d, which the relation still reports, the question asked having been about the reservoir.", "600.000000 stb/d, reached only once the well has been kicked off with lift gas to bring the outflow requirement down."]'::jsonb, 2, 'That case is dead because the outflow requirement stands above the inflow supply at every rate, which the inflow curve cannot see.'),
  ('nodal', 'beginner', 'module', 'm05-absolute-open-flow', 13, 'What should be quoted to a planner in place of an open flow?', '["The reservoir pressure on its own, dated wherever possible.", "A rate with the pressure it requires as a pair, such as BONNY-7 at 2595 stb/d needing 1442.500000 psia.", "The open flow with its reservoir pressure attached, which is enough to rebuild the curve.", "The saturated share of the open flow, which shows how much of the curve has bent."]'::jsonb, 1, 'A pair is checkable, and the fraction of open flow is the one job the open flow itself does well.'),
  ('nodal', 'beginner', 'module', 'm05-absolute-open-flow', 14, 'In a ranking of wells, what does the productivity index belong to and what does the reservoir pressure belong to?', '["The index to the completion and the rock, the reservoir pressure to the reservoir and the drawdown it offers.", "Both to the completion, which is why the two get quoted together.", "The index to the fluid and the reservoir pressure to the completion, which is why an open flow mixes the two of them up.", "The index to the reservoir and the reservoir pressure to the fluid, with the bubble point owned by the completion."]'::jsonb, 0, 'The bubble point belongs to the fluid and says how much of the range is straight, while the open flow belongs to all three at once.'),
  ('nodal', 'beginner', 'module', 'm05-absolute-open-flow', 15, 'Which two items must never leave an inflow study on their own?', '["A slope without its units, and a rate without its fluid named.", "A bubble point of 0 psia without a note that it is a modelling statement, and any inverse reading without its slope.", "An index without where the test sat, and an open flow without its reservoir pressure and its family.", "A reservoir pressure without its date, and a test rate without the drawdown it was taken at."]'::jsonb, 2, 'Three families reproduce BONNY-7''s test at 720.000000 stb/d and then disagree by 1155.555556 and 1091.197244 stb/d at 0 psia.'),
  ('nodal', 'beginner', 'module', 'm06-the-associate-reading', 1, 'Which of the two statements about a producing well does the Associate tier own?', '["The reservoir''s, that it delivers a rate at a flowing bottomhole pressure and more as that pressure falls.", "The tubing''s, that a bottomhole pressure is required to lift a rate.", "Both of them at once, since the operating point is the only place where a rate and a pressure may be quoted together.", "Neither, because a single production test cannot pin a curve without a second rate beside it."]'::jsonb, 0, 'Rate runs horizontally in stb/d and bottomhole pressure vertically in psia, absolute and never gauge, with nothing converted for you.'),
  ('nodal', 'beginner', 'module', 'm06-the-associate-reading', 2, 'Which four items fully define an inflow curve?', '["A reservoir pressure, an index, a skin and a drainage radius.", "A family, a reservoir pressure, a bubble point and a tubing size, because the curve is sampled against the string it feeds.", "A family, a reservoir pressure, a bubble point, and either coefficients or one test to pin the curve.", "A reservoir pressure, a bubble point, a water cut and a test rate, taken in that order."]'::jsonb, 2, 'From BONNY-7''s four, a composite at 2740 psia with a bubble point of 1300 psia pinned by 720 stb/d at 2380 psia, every other number follows.'),
  ('nodal', 'beginner', 'module', 'm06-the-associate-reading', 3, 'BONNY-7''s straight line and composite agree exactly down to 1300 psia. What is the first difference below it?', '["182.761709 stb/d at 783 psia, the first row below the join.", "10.855385 stb/d at 1174 psia, an amount no chart would separate, and it then grows without any limit.", "1155.555556 stb/d at 0 psia, because the two families stay identical at every pressure above the open flow itself.", "Zero, since a composite is defined as the straight line all the way down to a flowing pressure of 0 psia."]'::jsonb, 1, 'The last zero in that column sits at 1300 psia, and it is the bubble point rather than the test that puts it there.'),
  ('nodal', 'beginner', 'module', 'm06-the-associate-reading', 4, 'Where do FORCADOS-3''s straight line and composite readings change sign against one another?', '["At 2450 psia, the bubble point, where the curve begins to bend.", "At 3720 psia, the reservoir pressure, where both families read 0.000000 stb/d and a difference cannot carry a sign.", "At 1594 psia, where the difference of 180.248054 stb/d first becomes visible on a chart.", "At 2180 psia, the test pressure, because calibration forces every family through the test point."]'::jsonb, 3, 'At the bubble point the difference is -17.143440 stb/d, near the largest negative value anywhere in that column.'),
  ('nodal', 'beginner', 'module', 'm06-the-associate-reading', 5, 'Read as a straight line, FORCADOS-3''s below bubble test backs out 1.55844156 stb/d/psi. Why is that low?', '["Its test drawdown of 1540 psi was measured at the wrong datum.", "The straight line carries no bubble point at all, so it clamps the index to whatever the curve reaches at 2450 psia.", "The well had already bent before it was measured, so a smaller rate gets divided by the full drawdown.", "Vogel was used for the comparison, and Vogel reads low everywhere on an undersaturated well."]'::jsonb, 2, 'Of that 1540 psi the first 1270 psi took the pressure down to the bubble point, where the well really did obey its index.'),
  ('nodal', 'beginner', 'module', 'm06-the-associate-reading', 6, 'An engineer negates and inverts BONNY-7''s slope column to recover an index, and gets one answer at 2595 stb/d and another at 4195 stb/d. Which one is the well''s?', '["The one at 2595 stb/d, where the slope still holds minus 0.50000000 psi per stb/d above the bubble point.", "Both, an index recovered from the slope column being exact wherever that column is read.", "The one at 4195 stb/d, closest to the open flow of 4324.444444 stb/d where the curve is best resolved.", "Neither, a slope column carrying the shape of the family and never a productivity index."]'::jsonb, 0, 'The flat stretch ends at the bubble point of 1300 psia, below which the column reads minus 0.57666066 at 3243 stb/d and minus 1.57442483 at 4195 stb/d.'),
  ('nodal', 'beginner', 'module', 'm06-the-associate-reading', 7, 'What does the saturated block of a composite depend on?', '["The reservoir pressure and the bubble point taken together, since the block is whatever lies below the join on the curve.", "The productivity index and the bubble point alone, never on the reservoir pressure above the join.", "The productivity index, the bubble point and the reservoir pressure, which is why FORCADOS-3 carries the larger block.", "Vogel''s two published constants of 0.2 and 0.8, together with the test rate and pressure the curve was calibrated from."]'::jsonb, 1, 'FORCADOS-3 has the smaller index and still the larger saturated block, 2139.585450 against 1444.444444 stb/d.'),
  ('nodal', 'beginner', 'module', 'm06-the-associate-reading', 8, 'Multiplying 2.00000000 stb/d/psi by 1440.0000 psi returns 2880.000000 stb/d. What has that checked?', '["That the engine''s root find converged inside its own tolerance.", "That the index is the well''s own, the identity closing only above the bubble point.", "That Vogel''s shape has been fitted correctly below the bubble point of 1300 psia.", "That three printed numbers stand in an exact arithmetic relationship, with no band and no judgement."]'::jsonb, 3, 'Derive all three inputs from a below bubble test read as a straight line and the identity still closes, on a curve that is not the well.'),
  ('nodal', 'beginner', 'module', 'm06-the-associate-reading', 9, 'The published Jones case carries a bubble point of 0 psia and bends anyway. What is its signature?', '["A slope of -1.06482135 psi per stb/d held at every sampled rate.", "A slope that holds and then moves, exactly as BONNY-7''s does at 3243 stb/d where it leaves -0.50000000 psi per stb/d.", "A slope that is already moving at the very first sampled rate, with no flat stretch anywhere at all.", "A slope that steepens only below 700 psia, where free gas comes out of solution and takes the flow path away from the oil."]'::jsonb, 2, 'It runs from -1.06482135 psi per stb/d at 54.9405 stb/d to -4.03160570 at 1043.8686 stb/d, so a bending curve is no proof of a bubble point.'),
  ('nodal', 'beginner', 'module', 'm06-the-associate-reading', 10, 'Which conditions does the engine actually raise a warning about?', '["A wrong family, a wrong bubble point, a stale reservoir pressure.", "A test at or above the reservoir pressure, a non-positive index, and a Fetkovich n outside 0.5 to 1.0.", "Any straight line reading taken below the bubble point, and any rate above the open flow.", "A drawdown quoted in psig, and a rate and pressure that were never measured together."]'::jsonb, 1, 'It also flags Jones coefficients that miss their own test point by more than 2 percent of the reservoir pressure.'),
  ('nodal', 'beginner', 'module', 'm06-the-associate-reading', 11, 'What does the engine hand back in place of a NaN open flow?', '["An empty curve, a null operating point, a status and a warnings list, so downstream guards still fire.", "A zero open flow, with the returned status left unchanged.", "The last valid open flow it computed, so a caller comparing rates still has a number.", "A negative open flow, easy to test for and impossible to mistake for a real rate."]'::jsonb, 0, 'A NaN makes every downstream rate comparison false, so a caller sails straight past its own guards.'),
  ('nodal', 'beginner', 'module', 'm06-the-associate-reading', 12, 'On BONNY-7 a flowing pressure of 1566 psia is a drawdown of 1174 psi. Why is swapping those two dangerous?', '["The engine rejects a drawdown larger than the reservoir pressure.", "A drawdown is measured in psi and a flowing pressure in psia, so the swap gets caught by a unit check at the door.", "The swap moves the reading across the bubble point of 1300 psia, which the slope column would flag by leaving minus one over the index.", "Both pairs sit on the well''s own curve, giving 2348.000000 and 3121.144615 stb/d, and neither looks wrong."]'::jsonb, 3, 'Only the flowing pressure is measured during a test, the reservoir pressure coming from a build up, a survey or a model.'),
  ('nodal', 'beginner', 'module', 'm06-the-associate-reading', 13, 'Why is a closed round trip a better check than two numbers that merely look right?', '["It is the only check that needs no reservoir pressure, so it survives the stale pressure that every other check depends on.", "It compares the forward relation against the sampled table, so any disagreement localises the fault to one of the two.", "It tests the machinery rather than your confidence in it: 2880.000000 stb/d at 1600 psia and back again.", "It proves the family is right, since a family chosen wrongly for the well could not reproduce its own reading twice over."]'::jsonb, 2, 'The published cases close the same way on their tests, returning 900.000000, 700.000000 and 1100.000000 stb/d.'),
  ('nodal', 'beginner', 'module', 'm06-the-associate-reading', 14, 'Reading a gas inflow off its forty sampled rows costs how much, and in which direction?', '["One to three psi low through the body of the empirical families, and 12.910810 psi low at 8.8807 Mscf/d.", "Up to three psi, high or low depending on the rate requested.", "About one psi on every case alike, since forty rows spaced evenly in pressure are spaced evenly in rate as well.", "Nothing at all, the engine reading every inverse from the calibrated relation itself and never from the stored rows."]'::jsonb, 0, 'Nothing about a chord error is random, and the same shortcut moves a solved gas well by 0.638815 Mscf/d.'),
  ('nodal', 'beginner', 'module', 'm06-the-associate-reading', 15, 'Which question does the Associate tier leave unanswered?', '["What rate the reservoir gives at a stated flowing pressure, which needs a family and coefficients the tier never supplies.", "Whether the well flows at all, the relation holding no tubing, no wellhead, no lift and no clock.", "How much drawdown is available, the reservoir pressure being a snapshot and the bubble point a property of the fluid.", "What the absolute open flow is, since that needs a deliverability model fitted separately from the inflow curve."]'::jsonb, 1, 'Water breakthrough, packed perforations and growing skin move the real curve and appear nowhere until somebody takes a new test.'),
  ('nodal', 'beginner', 'final', null, 1, 'A morning report gives BONNY-7 at 1355.714057 stb/d and 2062.142971 psia. Which half of the well produced that pair?', '["Both halves produced it, since it is the one place where supply and requirement name the same pressure.", "The reservoir alone, because inflow owns every rate the well makes.", "The tubing alone, since a wellhead of 420 psia fixes the rate and the reservoir follows it up.", "Neither half, because an operating point is measured at surface and read back to depth afterwards."]'::jsonb, 0, 'Drop the wellhead to 280 psia and the same inflow curve gives 1424.991968 stb/d at 2027.504016 psia.'),
  ('nodal', 'beginner', 'final', null, 2, 'A partner supplies flowing pressures in psig, logged by a gauge hung above the perforations. What follows from handing those to this engine?', '["The engine rejects the deck, because psia is the only unit it will parse.", "The gauge offset cancels in the subtraction, so the index survives and only the printed pressures are wrong.", "Every drawdown is wrong twice over, by an atmosphere and by a column of fluid, and nothing is flagged.", "A conversion runs silently against a standard atmosphere, leaving the datum error as the only fault remaining."]'::jsonb, 2, 'The engine converts nothing and checks no datum, so both faults reach the printed index untouched.'),
  ('nodal', 'beginner', 'final', null, 3, 'Stimulation is proposed on the reservoir behind the published dead well case, which still carries an open flow of 600.000000 stb/d. What does that recorded status actually indict?', '["The reservoir, whose 600.000000 stb/d is too small to lift the column above it.", "The pairing of that inflow with an outflow requirement standing above it at every rate.", "The inflow relation, which must have been calibrated on a test taken while the well was already shut in and building up.", "The solver, which reported zero crossings after failing to bracket the single crossing that exists."]'::jsonb, 1, 'At 300 stb/d that case reads an inflow of 600.000000 psia against an outflow of 1890.000000 psia.'),
  ('nodal', 'beginner', 'final', null, 4, 'Following BONNY-7''s residual from minus 192.336636 psi at 4.324444 stb/d through minus 989.578610 psi to plus 12517.903995 psi, how many operating points has the well?', '["Two, since the residual is negative at both ends of its range.", "None, because a residual that starts negative means the column already outweighs the reservoir at the lowest sampled rate.", "Three, one at each of the rates whose residual is quoted, since the solver evaluates and reports crossings row by row.", "One, because that column changes sign once and each change of sign is a crossing."]'::jsonb, 3, 'The residual is the outflow requirement minus the inflow supply at a stated rate, so its zeros are the operating points.'),
  ('nodal', 'beginner', 'final', null, 5, 'Shifting the published straight line case to 2000 psia returns 3600.000000 stb/d, and an engineer writes a year beside it. Which part of that came from the engine?', '["Only the rate, since the depletion rule answers what the curve becomes and never answers when.", "Both, because holding the index fixes a decline rate as well.", "Neither, because a future open flow is a forecast and the engine refuses to produce one at all.", "Only the year, since the reservoir pressure of 2000 psia was chosen by the engineer and the rate then follows from it."]'::jsonb, 0, 'There is no material balance, no drive mechanism and no time axis anywhere in an inflow curve.'),
  ('nodal', 'beginner', 'final', null, 6, 'A curve is built on the wrong family with a bubble point that does not belong to the fluid. Which of those two faults raises anything?', '["The bubble point, which is checked against the reservoir pressure.", "The family, since a fitted family used on an undersaturated well is caught by the coefficient audit.", "Neither one, because the warnings cover a bad test, a bad index and out of range coefficients only.", "Both, though only after the curve has been sampled and the slope column has been inspected for a flat stretch."]'::jsonb, 2, 'A warning does fire on a test at or above the reservoir pressure, on a non-positive index, and on a Fetkovich n outside 0.5 to 1.0.'),
  ('nodal', 'beginner', 'final', null, 7, 'A consumer marches Beggs and Brill through its own PVT stack and hands the traverse over. What does the node solver need to know about how it was made?', '["The correlation used, so it can match its own z-factor route to it.", "Nothing at all, because it is handed two functions and looks only for where they agree.", "The tubing size and the wellhead pressure, so that the injected requirement can be rebuilt internally before the residual is formed.", "The water cut, so the inflow rate can be scaled to oil before the two statements are compared."]'::jsonb, 1, 'Only dry gas outflow is built in, by Cullender and Smith, because that needs nothing beyond a z-factor.'),
  ('nodal', 'beginner', 'final', null, 8, 'An input deck carries a test of 900 stb/d at 2700 psia against 3200 psia and, separately, a productivity index of 1.2 stb/d/psi. Which survives calibration?', '["The coefficient, since a stated index needs no calibration step.", "Neither, because two pieces of evidence for one coefficient raise a conflict warning and the curve is returned empty.", "Both, with the index used above the bubble point and the test used below it.", "The test, because a supplied test beats a supplied coefficient and returns 1.80000000 stb/d/psi."]'::jsonb, 3, 'Calibrating from that test reads 900.000000 stb/d back at 2700 psia, which is what calibration means rather than evidence.'),
  ('nodal', 'beginner', 'final', null, 9, 'A curve arrives with no inputs attached and a slope column holding minus 0.83333333 psi per stb/d twice before moving to minus 0.85470451, minus 1.33843239 and minus 2.55747877. Which family is it?', '["A Jones curve, whose slope moves at every sampled rate.", "A composite, whose slope is constant through the linear block and then climbs once past the join.", "A straight line whose sampling has drifted, since minus one over the index reproduces only the first two of those values exactly.", "A Vogel curve, because a slope that steepens toward the open flow is Vogel''s signature."]'::jsonb, 1, 'Minus one over 1.2 stb/d/psi is minus 0.83333333 psi per stb/d, and a composite reveals itself in that pattern and no other.'),
  ('nodal', 'beginner', 'final', null, 10, 'Neither well spends its budget: BONNY-7 runs at 677.857029 psi of drawdown and FORCADOS-3 at 1353.090778 psi. What holds each of them short?', '["The tubing, which sets the operating point and leaves the rest of the pressure budget unspent.", "The bubble point, past which more drawdown buys nothing.", "The engine''s own guard against a flowing pressure of 0 psia, which clamps the reported drawdown well before the budget is reached.", "The reservoir, whose average pressure falls as soon as drawdown is applied."]'::jsonb, 0, 'The largest drawdown available is the reservoir pressure itself, 2740 psi on one well and 3720 psi on the other.'),
  ('nodal', 'beginner', 'final', null, 11, 'An index is quoted to eight figures from a rate logged one month and a shut-in survey taken the next. What is wrong with that number?', '["Nothing, provided both pressures are absolute and share a datum.", "Only its precision, since eight figures cannot be justified by field instruments.", "The rate and the two pressures were never measured together, so it describes no state the well was ever in.", "The subtraction itself, because a reservoir pressure taken from a build up is an average over a drainage area and cannot enter a drawdown."]'::jsonb, 2, 'Only the flowing pressure is measured during a test; the reservoir pressure comes from a build up, a survey or a model.'),
  ('nodal', 'beginner', 'final', null, 12, 'Somebody types 1174 into BONNY-7''s flowing pressure field where 1174 psi of drawdown was intended. Which two rates does that confusion put on the table?', '["720.000000 and 2880.000000 stb/d, the test rate and the rate at the join.", "4133.021538 stb/d either way, since the two entries meet at the same point.", "3132.000000 and 3121.144615 stb/d, the straight line and composite readings at that pressure, which differ by only 10.855385 stb/d.", "2348.000000 and 3121.144615 stb/d, both genuine points on the well''s own curve, so neither looks wrong."]'::jsonb, 3, 'A flowing pressure of 1174 psia is a drawdown of 1566 psi, and a drawdown of 1174 psi is a flowing pressure of 1566 psia.'),
  ('nodal', 'beginner', 'final', null, 13, 'Of phase change, turbulence and extrapolation, which failure leaves no trace whatever in a slope column, and what is left to defend against it?', '["Extrapolation, defended only by knowing where the measurement sat, since it looks exactly like interpolation.", "Turbulence, defended by a multi-rate test.", "Phase change, defended by a bubble point measured on a laboratory sample of the fluid.", "Extrapolation, defended by the engine''s warning that a reading has passed the calibrating test."]'::jsonb, 0, 'FORCADOS-3''s straight line claims 5797.402597 stb/d at 0 psia from a single measurement taken at 2180 psia.'),
  ('nodal', 'beginner', 'final', null, 14, 'Two questions decide whether a straight line is honest on a given well. What does a reservoir pressure sitting at or below the bubble point settle straight away?', '["That the line is exact but only down to the bubble point.", "That the index must be recalibrated against a test taken below the bubble point before the line can be drawn.", "That no linear block exists anywhere on the curve, so the line has nothing on it to be exact about.", "That the well is a candidate for the composite, whose upper block would then carry the whole of the reading range."]'::jsonb, 2, 'The second question is whether the flowing pressure will stay above the bubble point at the rates intended.'),
  ('nodal', 'beginner', 'final', null, 15, 'FORCADOS-3 was tested at 2180 psia, below its bubble point of 2450 psia, and the test was read as a straight line. Carried all the way to 0 psia, what does that one decision cost?', '["Nothing at 0 psia, because both families meet again at the open flow.", "An open flow of 5797.402597 stb/d against a true 4135.949669, an overstatement of 1661.452928 stb/d.", "An understatement of 1661.452928 stb/d, since an index backed out low must give a low open flow everywhere below the calibrating test.", "A shortfall of 17.143440 stb/d, the size of the difference recorded at the bubble point."]'::jsonb, 1, 'The line reads low above the test and high below it, because calibration swings every family about the test point.'),
  ('nodal', 'beginner', 'final', null, 16, 'Between 2740 psia and 1300 psia on BONNY-7, one pair of families prints identical rates row by row while a third does not. Name the pair and the odd one out.', '["Vogel and the composite agree; the straight line is the odd one.", "The straight line and Vogel agree, since both are single block relations, while the composite carries a join.", "The straight line and the composite agree, and Vogel joins them at the bubble point where its own term falls to zero.", "The straight line and the composite agree exactly; Vogel is already 535.813953 stb/d short at 1300 psia."]'::jsonb, 3, 'All three do meet at 720.000000 stb/d at the test pressure of 2380 psia, which is agreement by construction.'),
  ('nodal', 'beginner', 'final', null, 17, 'Told the bubble point, the composite stops dividing a below bubble test rate by the test drawdown. What does it divide by instead, and what does that recover?', '["By both blocks evaluated down to the test pressure, recovering 0.98684211 stb/d/psi from 1500 stb/d at 1400 psia.", "By the drawdown to the bubble point only, recovering the linear block.", "By the saturated block alone, since a test below the join says nothing about the undersaturated part.", "By the reservoir pressure, which recovers the open flow directly and the index afterwards."]'::jsonb, 0, 'That expression stays linear in the index, which is why one division still pins the coefficient exactly.'),
  ('nodal', 'beginner', 'final', null, 18, 'A revised fluid study raises a well''s bubble point while its index and reservoir pressure stay where they were. What happens to the saturated block?', '["It shrinks, because less of the range is now linear.", "It is unchanged, since the block is fixed by the open flow.", "It grows in proportion, being the index times the bubble point over 1.8 with no reservoir pressure in it.", "It grows, but only until the bubble point reaches the reservoir pressure, beyond which the block is recomputed from Vogel''s constants."]'::jsonb, 2, 'That is why FORCADOS-3 carries the larger saturated block, 2139.585450 stb/d, on the smaller index.'),
  ('nodal', 'beginner', 'final', null, 19, 'An import drops the bubble point and it defaults to 0 psia. Applied to BONNY-7, what does the resulting curve show and what gives it away?', '["An open flow of 3233.247201 stb/d on a Vogel shape.", "An open flow of 5480.000000 stb/d on a slope that never moves off minus 0.50000000 psi per stb/d.", "An open flow of 4324.444444 stb/d, unchanged, because the saturated block is rebuilt from the reservoir pressure whenever a bubble point is missing.", "A warning, raised as soon as a bubble point of 0 psia is combined with a test taken above it."]'::jsonb, 1, 'Set the bubble point at or above the reservoir pressure instead and the relation clamps, becoming Vogel from the first psi.'),
  ('nodal', 'beginner', 'final', null, 20, 'A reviewer defends applying Vogel to an undersaturated well as the conservative choice. Why does that defence fail?', '["Vogel reads high on an undersaturated well, not low.", "Vogel raises no warning, so the reader has no way of telling that a margin has been introduced at all.", "Vogel needs an index, and an undersaturated well cannot supply one.", "A margin of 1091.197244 stb/d that nobody chose lands on top of whatever margin they thought they had added."]'::jsonb, 3, 'At BONNY-7''s bubble point of 1300 psia Vogel is already 535.813953 stb/d under the composite, bending a part of the curve that does not bend.'),
  ('nodal', 'beginner', 'final', null, 21, 'Multi-rate readings show a well curving although its fluid never comes out of solution anywhere in the drainage area. Which families does that evidence select?', '["Fetkovich or Jones, since the curvature must be turbulence once phase change has been ruled out.", "Vogel, whose shape fits any bending curve.", "The composite, since a bend always implies a join and the join must sit at whatever pressure the bending begins.", "The straight line, because a well with no phase change is linear and the curvature is a sampling artefact."]'::jsonb, 0, 'The engine cannot separate a gas effect from a turbulence effect, since it carries no relative permeability curve and no PVT.'),
  ('nodal', 'beginner', 'final', null, 22, 'One direction of reading substitutes and returns at once; the other brackets, iterates and converges. Why is the second not simply five rearranged formulas?', '["Because four of the five families cannot be rearranged at all.", "Because a bracketed search is faster than a closed form once the curve has been sampled at forty pressures.", "Five hand written inverses can go stale behind a new forward relation and return a confident wrong number.", "Because rearranging would lose the sign of the slope, and an inverse reading needs monotonicity to be reported as a single value."]'::jsonb, 2, 'The closed forms survive in the oracle that checks the engine, which is where a second opinion belongs.'),
  ('nodal', 'beginner', 'final', null, 23, 'Brent''s method mixes bisection with a secant and an inverse quadratic step. When does it fall back on bisection, and what does bisection contribute?', '["It falls back at the join of a composite, where the slope is discontinuous.", "It falls back whenever the clever step misbehaves, and bisection keeps the half that holds the sign change.", "It falls back only at the open flow, where bisection returns zero pressure in place of a root.", "It falls back once per reading, and bisection sets the bracket from 0 psia to reservoir pressure."]'::jsonb, 1, 'A bracketed search walks across a composite''s join without noticing it, which is exactly what rearranging by hand cannot do.'),
  ('nodal', 'beginner', 'final', null, 24, 'Two gas cases are sampled at forty pressures each, yet one pays 12.910810 psi of bias at its lowest sampled rate and another only 1.477901 psi. What separates them?', '["The turbulent case carries fewer sampled rows than the other one, so its chord spans a wider gap between neighbouring pressures.", "The two biases were read at different rates, and one measured at 8.8807 Mscf/d cannot be set beside one taken much higher up a curve.", "The turbulent case is quoted in MMscf/d rather than Mscf/d, so the same bias is printed on a scale a thousand times larger.", "The lower exponent gives a steeper approach to the reservoir pressure, so the chord spans a harder bend."]'::jsonb, 3, 'Walking evenly in pressure is wildly uneven in rate, and the widest rate interval always sits where the curve bends hardest.'),
  ('nodal', 'beginner', 'final', null, 25, 'Two engineers argue over whether chord errors might average out across many table readings. Which of them is right?', '["The one who says they do not, because every chord reading is low and nothing about the error is random.", "The one who says they cancel over a wide enough rate range.", "Neither, since a chord bias reverses sign at the curve''s inflection and so cancels in part.", "The one who says they cancel, provided the readings are spread evenly over the sampled rows."]'::jsonb, 0, 'Biases run minus 1.477901, minus 0.355211, minus 0.404982 and minus 0.854137 psi across one published family, all in the same direction.'),
  ('nodal', 'beginner', 'final', null, 26, 'A chord read at 8.8807 Mscf/d returns 3147.834757 psia where the relation gives 3160.745567 psia. Carried into a node solution, what does that error do?', '["It cancels, since the outflow requirement is read from the same table and carries the identical chord error at that rate.", "It raises the solved rate, because a lower inflow pressure at a stated rate leaves more of the column''s requirement to be met by the reservoir.", "It biases the solved rate low, taking one published gas well from 11335.720032 to 11335.081217 Mscf/d.", "It has no effect, because the solver evaluates the relation directly at each trial rate rather than reading the sampled table."]'::jsonb, 2, 'The deviated big-tubing well shifts by minus 1.031002 Mscf/d in the same direction, small and systematic.'),
  ('nodal', 'beginner', 'final', null, 27, 'A planner prices another 100 stb/d on BONNY-7 at minus 0.50000000 psi per stb/d while the well already runs at 4195 stb/d. What is wrong with that price?', '["Nothing, since the index holds across the whole curve.", "The price is right but the rate is not, since 4195 stb/d sits above the open flow of 4324.444444 stb/d.", "The slope is quoted with the wrong sign for an increment above the operating point.", "The local price there is minus 1.57442483 psi per stb/d, so the pressure the barrels cost is badly understated."]'::jsonb, 3, 'That flat price is genuine only out to 0.60007708 of the open flow, at 2595 stb/d and 1442.500000 psia.'),
  ('nodal', 'beginner', 'final', null, 28, 'Three families reproduce one test exactly and then part by more than a thousand stb/d at the far end. Where does the evidence that would separate them sit?', '["Everywhere below the test, which is precisely where no measurement exists to be compared against.", "At the test, which is the one checkable pressure.", "At the bubble point, where the composite and the straight line still agree and Vogel does not.", "In the slope column, whose first moving row identifies the family without any second model needing to be run at all."]'::jsonb, 0, 'Vogel is 1091.197244 stb/d under the composite at 0 psia while the straight line is 1155.555556 stb/d over it.'),
  ('nodal', 'beginner', 'final', null, 29, 'A report prints open flow in its own column, away from the inflow readings, as though a second model had made it. What is it really?', '["A separate extrapolation fitted beyond the last sampled row, where the relation itself has nothing left to report.", "The same forward reading as every other row, taken at a flowing pressure of 0 psia.", "A calibration output, since Vogel solves for it directly from a test and the other families then match that convention.", "A search bound computed by the solver before any forward reading is attempted, which is why it prints in a column of its own."]'::jsonb, 1, 'On a straight line it is the index times the reservoir pressure, and on a composite it is two blocks summed.'),
  ('nodal', 'beginner', 'final', null, 30, 'Two wells report 4324.444444 and 4135.949669 stb/d and a manager calls them equivalent. Which quantity settles which completion is better?', '["The open flow, which already contains the index and the reservoir pressure together, so ranking on it ranks on everything at once.", "The bubble point, 1300 psia against 2450 psia, which fixes how much of each curve is straight and so how much drawdown is cheap.", "The productivity index, 2.00000000 against 1.57194033 stb/d/psi, since it is what one psi of drawdown buys.", "The reservoir pressure, 2740 psia against 3720 psia, since the well with more pressure available has more to lose to a poor completion."]'::jsonb, 2, 'Those near equal open flows are a better completion and a stronger reservoir cancelling each other out.'),
  ('nodal', 'beginner', 'final', null, 31, 'A note passes on an index of 1.55844156 stb/d/psi with nothing beside it. Which missing fact makes the number unusable?', '["Where the calibrating test sat, since that one was taken below a bubble point and reads low as a result.", "Its units, which could be psi per stb/d instead.", "The reservoir pressure, without which an index cannot be turned into a drawdown.", "The family, since a Vogel well has no index at all and any figure quoted from one is a price at a rate with the rate stripped away."]'::jsonb, 0, 'The composite backs out 1.57194033 stb/d/psi from the same test, an error of minus 0.01349877 stb/d/psi.'),
  ('nodal', 'beginner', 'final', null, 32, 'Asked how hard two wells are being worked, what should be tabulated for each, and what does the pressure beside it add?', '["The drawdown, with the pressure confirming the datum.", "The fraction of open flow, with the required pressure saying whether that working point is reachable.", "The rate in stb/d, with the pressure showing how much of the budget is left unspent.", "The open flow, with the pressure identifying which family produced it."]'::jsonb, 1, 'BONNY-7 needs 301.955326 psia at 0.97006680 of its open flow and FORCADOS-3 needs 420.700695 psia at 0.97003115.'),
  ('nodal', 'beginner', 'final', null, 33, 'A scheduling tool asks the published Fetkovich case, whose open flow is 124.766308 stb/d, for the pressure at a higher rate. What comes back?', '["A warning, because the rate exceeds the open flow and the relation has no pressure to offer beyond that point.", "The pressure at the open flow itself, since the search clamps to the nearest point on the relation before returning.", "Nothing at all, because the returned curve is empty and the operating point is null whenever a request cannot be bracketed.", "Zero pressure, a boundary reply from outside the bracket that prints exactly like a solved root."]'::jsonb, 3, 'What guarantees a root inside the bracket is that the relation reads zero at one end and the open flow at the other.'),
  ('nodal', 'beginner', 'final', null, 34, 'A spreadsheet ranks eight wells on open flow alone, mixing oil rows with gas rows. Name the two conditions that ranking has broken.', '["The same bubble point for every well and the same drawdown at each calibrating test, without which the rates are not comparable.", "The same inflow family for all eight and the same datum for every bottomhole pressure quoted, so that one open flow means what the next does.", "One reservoir pressure for all of them or each one stated, and one fluid with one unit throughout.", "The same sampling density and the same number of decimal places, since an open flow to six figures invites a comparison its inputs cannot support."]'::jsonb, 2, 'Oil open flows are in stb/d and gas in Mscf/d, and confusing Mscf/d with MMscf/d is the commonest unit error here.'),
  ('nodal', 'beginner', 'final', null, 35, 'Why is the open flow the most sensitive figure an inflow relation prints, whatever precision it carries?', '["It sits at the steepest end of the curve, minus 1.57442483 psi per stb/d against minus 0.50000000 higher up.", "Because it is computed by a root find rather than a substitution.", "Because it is the only reading taken outside the sampled rows.", "Because it depends on the bubble point, the least well known of the inputs that define the curve."]'::jsonb, 0, 'BONNY-7 reaches 0.90000000 of it at 649.199606 psia and 0.97006680 at 301.955326 psia, so the last of it is bought very dearly.'),
  ('nodal', 'beginner', 'final', null, 36, 'Step three of the capstone feeds the test pressure back in and the test rate does not come back exactly. What does the procedure say to do next?', '["Move on, since a small residual at the test is expected from a root find and does not disturb the readings that follow.", "Switch family, because only a composite reproduces its own test exactly and the others match it to within a tolerance.", "Continue to the join identity, which will confirm the calibration independently if the three inputs are consistent with the printed rate.", "Stop there, because every later answer is built on that calibration and all of them fail together."]'::jsonb, 3, 'The published cases return 900.000000, 700.000000, 600.000000, 1500.000000 and 1100.000000 stb/d against tests of the same size.'),
  ('nodal', 'beginner', 'final', null, 37, 'Six reported answers rest on one calibration step. What does that structure mean for the way they go wrong?', '["They go wrong singly, each in its own reading, since every answer is taken from the relation independently.", "They go wrong together, so one misplaced test corrupts every one of the six at once.", "Only the open flow goes wrong, since the readings between the reservoir pressure and the test are pinned by the measurement itself.", "They go wrong in pairs, the forward readings first and the inverse readings only once the bracket is affected."]'::jsonb, 1, 'Locating the test against the bubble point is the step that decides which block carries it and therefore what the index means.'),
  ('nodal', 'beginner', 'final', null, 38, 'The Professional tier''s curve does not fall. Which property of the inflow curve does it lack, and what does losing that cost a solver?', '["Monotonicity, and losing it means one bracketed search can no longer promise a unique answer.", "Continuity, and losing it means the join can no longer be crossed by a search that steps in from one side.", "Its bracket, and losing it means an outflow requirement can no longer be evaluated at a flowing pressure of 0 psia at all.", "Its units, and losing them means rate and pressure can no longer be plotted on one pair of axes."]'::jsonb, 0, 'An outflow curve is two terms pulling opposite ways, so its requirement falls, reaches a minimum and then rises.'),
  ('nodal', 'beginner', 'final', null, 39, 'Six things leave an inflow analysis. Which single one of them rebuilds the other five, and which of them can rebuild it?', '["The open flow rebuilds them, and the index rebuilds the open flow, the two being tied by the reservoir pressure.", "The index rebuilds them, and the reservoir pressure rebuilds the index once the calibrating test rate is known.", "The calibrated relation rebuilds them all, and nothing else on the list can rebuild the relation.", "The inverse readings rebuild them, since a pair of a rate and a pressure is checkable and the slope column follows from a sequence of such pairs."]'::jsonb, 2, 'That relation is a family, a reservoir pressure, a bubble point and the calibrating test, four items in all.'),
  ('nodal', 'beginner', 'final', null, 40, 'Two of the capstone traps are a slope carried past the join and a reading taken beyond the calibrating test. Which one announces itself?', '["The reading beyond the test does, once it passes the bubble point.", "The carried slope does, moving from minus 0.50000000 to minus 0.57666066 psi per stb/d at 3243 stb/d.", "Both do, the first in the slope column and the second in the returned curve''s warnings list.", "Neither does, since a sampled curve prints the same decimals wherever the reading was taken."]'::jsonb, 1, 'Extrapolation has no signature at all, because from the inside it looks exactly like interpolation.'),
  ('nodal', 'beginner', 'final', null, 41, 'An answer sheet mixes MMscf/d with stb/d and quotes a pressure in psig. How much of that will the engine put right?', '["The gas unit only, which is normalised to Mscf/d on output.", "The pressure only, since a psig value is caught by comparison with the reservoir pressure.", "None of it, because field units are never converted and no unit fault raises a warning of any kind.", "All of it, because the calibration step normalises every input before a coefficient is pinned."]'::jsonb, 2, 'The travelling units are stb/d, Mscf/d, psia, ft, degF, in, stb/d/psi and psi per stb/d.'),
  ('nodal', 'beginner', 'final', null, 42, 'Handed BONNY-7''s inverse readings of 1767.000000, 1442.500000 and 1105.576792 psia, what does a column of tubing requirements beside them let you build?', '["The productivity index, from the spacing of the three pressures.", "The open flow, by extending the three readings down to a flowing pressure of 0 psia and taking the limit of the sequence.", "The saturated share, once each pressure has been placed on its own side of the bubble point.", "The residual at each rate, whose zeros are the operating points the next tier goes looking for."]'::jsonb, 3, 'Those readings sit at 1946, 2595 and 3243 stb/d, the last of them already past the join at 1300 psia.');
